import * as lng from '@solidtv/renderer';
import { Config, DOM_RENDERING } from './config.js';
import { DOMRendererMain, loadFontToDom } from './dom-renderer/domRenderer.js';
import {
  DomRendererMainSettings,
  IRendererNode,
  IRendererNodeProps,
} from './dom-renderer/domRendererTypes.js';
import { FontLoadOptions } from './intrinsicTypes.js';
import { hexColor } from '../utils.js';

export type SdfFontType = 'ssdf' | 'msdf';
// Global renderer instance: can be either the Lightning or DOM implementation
export let renderer: lng.RendererMain | DOMRendererMain;

export const getRenderer = () => renderer;

export function startLightningRenderer(
  options: lng.RendererMainSettings | DomRendererMainSettings,
  rootId: string | HTMLElement = 'app',
) {
  // Inlined (not isDomRendererActive()) so bundlers can fold DOM_RENDERING to
  // false and drop the DOMRendererMain branch + import in WebGL builds.
  const enableDomRenderer = DOM_RENDERING && Config.domRendererEnabled;

  renderer = enableDomRenderer
    ? new DOMRendererMain(options, rootId)
    : new lng.RendererMain(options, rootId);
  return renderer;
}

export interface SplashOptions {
  /** Image source for the centered logo. */
  src: string;
  /** Width of the centered image. */
  w: number;
  /** Height of the centered image. */
  h: number;
  /** Fullscreen background color (8-char hex string or color number). */
  bgColor?: string | number;
}

export interface SplashController {
  /** Immediately remove the splash nodes from the scene. */
  destroy: () => void;
  /** Fade the splash out over `duration` ms (default 500), then remove it. */
  fadeOut: (duration?: number) => Promise<void>;
}

/**
 * Renders a fullscreen splash screen by creating two renderer nodes directly
 * (outside the Solid scene graph): a fullscreen background filled with
 * `bgColor` and the `src` image sized to `w`/`h` and centered on screen.
 *
 * Returns a controller to remove the splash immediately (`destroy`) or animate
 * it out via alpha (`fadeOut`).
 */
export function splash(options: SplashOptions): SplashController {
  const { src, w, h, bgColor = 0x000000ff } = options;
  const root = renderer.root as IRendererNode;

  const background = renderer.createNode({
    x: 0,
    y: 0,
    w: root.w,
    h: root.h,
    color: hexColor(bgColor),
    parent: root as any,
    zIndex: 1000
  });

  const image = renderer.createNode({
    x: (root.w - w) / 2,
    y: (root.h - h) / 2,
    w,
    h,
    src,
    parent: background as any,
  });

  const nodes = [background, image];

  renderer.stage.drawFrame();

  const destroy = () => {
    for (const node of nodes) {
      (node as unknown as lng.INode).destroy();
    }
  };

  return {
    destroy,
    async fadeOut(duration = 300) {
      await Promise.all(
        nodes.map((node) =>
          node.animate({ alpha: 0 }, { duration }).start().waitUntilStopped(),
        ),
      );
      destroy();
    },
  };
}

export async function loadFonts(fonts: FontLoadOptions[]) {
  // Inlined so the loadFontToDom branch + import tree-shake in WebGL builds.
  const enableDomRenderer = DOM_RENDERING && Config.domRendererEnabled;
  await Promise.all(
    fonts.map((font) => {
      // WebGL — SDF
      if (
        renderer.stage.renderer.mode === 'webgl' &&
        'type' in font &&
        (font.type === 'msdf' || font.type === 'ssdf')
      ) {
        return renderer.stage.loadFont('sdf', font);
      }
      // Canvas — Web
      if ('fontUrl' in font) {
        if (enableDomRenderer) {
          loadFontToDom(font);
        } else if (renderer.stage.renderer.mode !== 'webgl') {
          return renderer.stage.loadFont('canvas', font);
        }
      }
    }),
  );
}
